        return [tuple(v.hex() if type(v) is bytes else v for v in row) for row in db.execute('SELECT * FROM effects ORDER BY request_id')]

def unchanged(operation,kind=DriverException):
    before=(ground(),effects())
    try:operation()
    except kind:pass
    else:raise AssertionError('Expected rejection')
    equal((ground(),effects()),before)

